39	    enum class State
40	    {
41	        DOWNLOADED,
42	        /**
43	         * When file segment is first created and returned to user, it has state EMPTY.
44	         * EMPTY state can become DOWNLOADING when getOrSetDownaloder is called successfully
45	         * by any owner of EMPTY state file segment.
46	         */
47	        EMPTY,
48	        /**
49	         * A newly created file segment never has DOWNLOADING state until call to getOrSetDownloader
50	         * because each cache user might acquire multiple file segments and reads them one by one,
51	         * so only user which actually needs to read this segment earlier than others - becomes a downloader.
52	         */
53	        DOWNLOADING,
54	        /**
55	         * Space reservation for a file segment is incremental, i.e. downaloder reads buffer_size bytes
56	         * from remote fs -> tries to reserve buffer_size bytes to put them to cache -> writes to cache
57	         * on successful reservation and stops cache write otherwise. Those, who waited for the same file
58	         * file segment, will read downloaded part from cache and remaining part directly from remote fs.
59	         */
60	        PARTIALLY_DOWNLOADED_NO_CONTINUATION,
61	        /**
62	         * If downloader did not finish download of current file segment for any reason apart from running
63	         * out of cache space, then download can be continued by other owners of this file segment.
64	         */
65	        PARTIALLY_DOWNLOADED,
66	        /**
67	         * If file segment cannot possibly be downloaded (first space reservation attempt failed), mark
68	         * this file segment as out of cache scope.
69	         */
70	        SKIP_CACHE,
71	    };
