116	
117	    assertNotDetached(segment_lock);
118	
119	    if (downloader_id.empty())
120	    {
121	        assert(download_state != State::DOWNLOADING);
122	
123	        if (download_state != State::EMPTY
124	            && download_state != State::PARTIALLY_DOWNLOADED)
125	            return "None";
