283	{
284	    if (!size)
285	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR, "Attempt to write zero size cache file");
286	
287	    if (availableSize() < size)
288	        throw Exception(
289	            ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
290	            "Not enough space is reserved. Available: {}, expected: {}", availableSize(), size);
