299	    cache_writer = std::make_unique<WriteBufferFromFile>(download_path, size + 1);
300	
301	    try
302	    {
303	        cache_writer->write(from, size);
304	    }
305	    catch (Exception & e)
306	    {
307	        wrapWithCacheInfo(e, "while writing into cache", segment_lock);
