658:        ///                         ^
659:        ///                         download_offset
660:        /// requested_range:    [__________]
661:        ///                     ^
662:        ///                     file_offset_of_buffer_end
663:
664:        auto download_offset = file_segment->getDownloadOffset();
665:        if (download_offset == file_offset_of_buffer_end)
666:        {
667:            /// TODO: makes sense to reuse local file reader if we return here with CACHED read type again?
668:            implementation_buffer = getImplementationBuffer(*current_file_segment_it);
669:
670:            return true;
671:        }
672:        else if (download_offset < file_offset_of_buffer_end)
673:            throw Exception(
674:                ErrorCodes::LOGICAL_ERROR, "Expected {} >= {} ({})", download_offset, file_offset_of_buffer_end, getInfoForLog());
675:    }
676:
677:    if (read_type == ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE)
678:    {
679:        /**
680:        * ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE means that on previous getImplementationBuffer() call
681:        * current buffer successfully called file_segment->getOrSetDownloader() and became a downloader
682:        * for this file segment. However, the downloader's term has a lifespan of 1 nextImpl() call,
683:        * e.g. downloader reads buffer_size byte and calls completeBatchAndResetDownloader() and some other
684:        * thread can become a downloader if it calls getOrSetDownloader() faster.
685:        *
686:        * So downloader is committed to download only buffer_size bytes and then is not a downloader anymore,
687:        * because there is no guarantee on a higher level, that current buffer will not disappear without
688:        * being destructed till the end of query or without finishing the read range, which he was supposed
689:        * to read by marks range given to him. Therefore, each nextImpl() call, in case of
690:        * READ_AND_PUT_IN_CACHE, starts with getOrSetDownloader().
691:        */
692:        implementation_buffer = getImplementationBuffer(*current_file_segment_it);
693:    }
694:
695:    return true;
696:}
