969:off_t CachedReadBufferFromRemoteFS::seek(off_t offset, int whence)
970:{
971:    if (initialized)
972:        throw Exception(ErrorCodes::CANNOT_SEEK_THROUGH_FILE, "Seek is allowed only before first read attempt from the buffer");
973:
974:    if (whence != SEEK_SET)
975:        throw Exception(ErrorCodes::CANNOT_SEEK_THROUGH_FILE, "Only SEEK_SET allowed");
976:
977:    first_offset = offset;
978:    file_offset_of_buffer_end = offset;
979:    size_t size = getTotalSizeToRead();
980:    initialize(offset, size);
981:
982:    return offset;
983:}
